"""Word-level timing of a narration track.

Each scene's voice-over lives in ``assets/narration`` as three files
sharing a stem, e.g. ``01-introduction``:

* ``01-introduction.mp3``        the audio (wav, m4a, flac also work)
* ``01-introduction.txt``        the script, written as it is spoken
                                  ("twenty thousand", not "20,000")
* ``01-introduction.words.tsv``  word timings, generated by
                                  ``tools/align_narration.py``

Scenes refer to moments in the audio by word, not by raw seconds, so a
re-recorded voice-over only needs re-aligning, not re-timing by hand::

    cues = narration.cues({
        "low_hz": ("twenty", 1),          # start of 1st "twenty"
        "high_hz": ("twenty", 2),         # start of 2nd "twenty"
        "end_hear": ("hear", 1, "end"),   # end of 1st "hear"
        "manual": 12.5,                   # plain seconds also work
    })
    cues.low_hz  # -> 2.59
"""

import csv
import re
from dataclasses import dataclass
from pathlib import Path
from types import SimpleNamespace

import av

from .paths import NARRATION_DIR

AUDIO_SUFFIXES = (".wav", ".mp3", ".m4a", ".aac", ".flac", ".ogg")

Anchor = float | str | tuple


@dataclass(frozen=True)
class Word:
    """One aligned word: its position in the script and its timing."""

    index: int
    text: str
    start: float
    end: float


def normalize(word: str) -> str:
    """Lower-case a word and strip punctuation, keeping apostrophes."""
    return re.sub(r"[^a-z0-9']", "", word.lower().replace("’", "'"))


class Narration:
    """Audio file plus word timings for one scene's voice-over."""

    def __init__(self, audio_path: Path, words: list[Word]):
        self.audio_path = audio_path
        self.words = words
        with av.open(str(audio_path)) as container:
            self.duration = container.duration / av.time_base

    @classmethod
    def load(cls, stem: str, directory: Path = NARRATION_DIR) -> "Narration":
        """Load ``<stem>.<audio>`` and ``<stem>.words.tsv``."""
        audio = next(
            (directory / f"{stem}{suffix}" for suffix in AUDIO_SUFFIXES
             if (directory / f"{stem}{suffix}").exists()),
            None,
        )
        if audio is None:
            raise FileNotFoundError(f"No audio for '{stem}' in {directory}")
        timings = directory / f"{stem}.words.tsv"
        if not timings.exists():
            raise FileNotFoundError(
                f"{timings.name} is missing. Generate it with:\n"
                f"  python tools/align_narration.py {stem}"
            )
        return cls(audio, read_words(timings))

    def find(self, word: str, occurrence: int = 1) -> Word:
        """Return the ``occurrence``-th (1-based) match of ``word``."""
        target = normalize(word)
        matches = [w for w in self.words if w.text == target]
        if len(matches) < occurrence:
            raise KeyError(
                f"'{word}' occurrence {occurrence} not found "
                f"({len(matches)} in transcript)"
            )
        return matches[occurrence - 1]

    def time_of(self, anchor: Anchor) -> float:
        """Resolve an anchor to seconds into the audio.

        An anchor is seconds (float), a word (its first occurrence), or a
        tuple ``(word, occurrence)`` / ``(word, occurrence, "end")``.
        """
        if isinstance(anchor, (int, float)):
            return float(anchor)
        if isinstance(anchor, str):
            word, occurrence, edge = anchor, 1, "start"
        else:
            word, occurrence, *rest = anchor
            edge = rest[0] if rest else "start"
        found = self.find(word, occurrence)
        return found.end if edge == "end" else found.start

    def cues(self, anchors: dict[str, Anchor]) -> SimpleNamespace:
        """Resolve a mapping of cue names to anchors into seconds."""
        return SimpleNamespace(
            **{name: self.time_of(anchor) for name, anchor in anchors.items()}
        )


def read_words(path: Path) -> list[Word]:
    """Read a ``.words.tsv`` file (columns: index, word, start, end)."""
    with path.open(newline="", encoding="utf-8") as handle:
        rows = csv.DictReader(
            (line for line in handle if not line.startswith("#")),
            delimiter="\t",
        )
        return [
            Word(int(row["index"]), normalize(row["word"]),
                 float(row["start"]), float(row["end"]))
            for row in rows
        ]


def write_words(path: Path, words: list[Word], source: str = "") -> None:
    """Write word timings as a ``.words.tsv`` file."""
    with path.open("w", newline="", encoding="utf-8") as handle:
        if source:
            handle.write(f"# aligned from {source}\n")
        writer = csv.writer(handle, delimiter="\t", lineterminator="\n")
        writer.writerow(["index", "word", "start", "end"])
        for word in words:
            writer.writerow(
                [word.index, word.text, f"{word.start:.2f}", f"{word.end:.2f}"]
            )
